 if(a.type==='next'){route='flight';if(s.phase>=1&&s.phase<4){s.phase++;if(s.phase===4){done('launch');if(!s.flown.includes(s.mission))s.flown.push(s.mission);route='report';}}}
 if(a.type==='repeat'){s.phase=0;route='prepare';message='Ready to try again. Your rocket, checks and discoveries stay saved.';}
 if(a.type==='demo'){if(a.id==='thrust')s.thrust=s.thrust%3+1;if(a.id==='mass')s.mass=s.mass%3+1;if(a.id==='air')s.vacuum=!s.vacuum;s.tested=a.id==='run';if(s.tested)done('thrust');route='demo';}
